parameters.jsCode:
const body = $json.body || $json;
const data = body.data || body;

const binaAdi = (data.binaAdi || data.building || 'Belirtilmemiş Tesis/Site').trim();
const blokDaire = (data.blokDaire || data.unit || 'Genel Ortak Alan').trim();
const talepMetni = (data.talep || data.description || 'Arıza detayı girilmedi').toLowerCase();
const bildirenKisi = (data.adSoyad || data.name || 'Site Sakini').trim();
const telefon = (data.telefon || data.phone || '-').trim();

let kategori = 'GENEL_BAKIM';
let taseronFirma = 'Alo Yönetim Genel Saha Teknik Ekibi';
let hedefSlaSaat = 24;

if (talepMetni.includes('asansör') || talepMetni.includes('kabin') || talepMetni.includes('katta kaldı')) {
  kategori = 'ASANSOR_BAKIM';
  taseronFirma = 'Anlaşmalı Asansör Yetkili Servisi (A Tipi Muayene)';
  hedefSlaSaat = 2;
} else if (talepMetni.includes('su') || talepMetni.includes('hidrofor') || talepMetni.includes('vana') || talepMetni.includes('gider')) {
  kategori = 'MEKANIK_TESISAT';
  taseronFirma = 'Sıhhi Tesisat & Hidrofor Bakım Servisi';
  hedefSlaSaat = 4;
} else if (talepMetni.includes('elektrik') || talepMetni.includes('trafo') || talepMetni.includes('jeneratör') || talepMetni.includes('sigorta')) {
  kategori = 'ELEKTRIK_ENERJI';
  taseronFirma = 'Yetkili Elektrik & Jeneratör Teknik Servisi';
  hedefSlaSaat = 3;
} else if (talepMetni.includes('yangın') || talepMetni.includes('dedektör') || talepMetni.includes('sprinkler')) {
  kategori = 'YANGIN_GUVENLIK';
  taseronFirma = 'Yangın Güvenlik & Algılama Sistemleri Servisi';
  hedefSlaSaat = 1;
}

const workOrderId = `ALOWKO-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`;

return [{
  json: {
    workOrderId,
    binaAdi,
    blokDaire,
    kategori,
    taseronFirma,
    hedefSlaSaat,
    talepMetni,
    bildirenKisi,
    telefon,
    dispatchedAt: new Date().toISOString()
  }
}];
